# ---------------------------------------------------
# FUNÇÕES AUXILIARES
# ---------------------------------------------------

def remover_acentos(texto):
    return ''.join(
        c for c in unicodedata.normalize('NFD', texto)
        if unicodedata.category(c) != 'Mn'
    )

def limpar_site(url):
    if not url:
        return ""
    url = url.strip().lower()
    url = re.sub(r"^https?:\/\/", "", url, flags=re.IGNORECASE)
    url = re.sub(r"^www\.", "", url, flags=re.IGNORECASE)
    url = remover_acentos(url)
    url = re.sub(r"[^a-z0-9\.\-\/]", "", url)
    url = url.rstrip("/")
    return url

def gerar_avatar(nome):
    nome = nome.strip().upper()
    if not nome:
        return "?"
    partes = nome.split()
    if len(partes) == 1:
        return partes[0][0]
    return partes[0][0] + partes[1][0]

def obter_instagram_handle(valor):
    if not valor:
        return ""
    valor = valor.strip()
    valor = re.sub(r"^https?:\/\/(www\.)?instagram\.com\/", "", valor, flags=re.IGNORECASE)
    valor = valor.strip("/")
    valor = valor.lstrip("@")
    if valor:
        valor = "@" + valor
    return valor

def obter_facebook_handle(valor):
    if not valor:
        return ""
    valor = valor.strip()
    valor = re.sub(r"^https?:\/\/(www\.)?facebook\.com\/", "", valor, flags=re.IGNORECASE)
    valor = valor.strip("/")
    return valor

def empresa_tem_dados(emp):
    return bool(emp.get("nome", "").strip())

def formatar_url(url):
    if not url:
        return ""
    url = url.strip()
    if not url.startswith("http"):
        url = "https://" + url
    return url

# ---------------------------------------------------
# SUPABASE — USUÁRIOS / AUTH
# ---------------------------------------------------

def login_supabase(email: str, senha: str):
    try:
        res = supabase.auth.sign_in_with_password({"email": email, "password": senha})
        return res.user, None
    except Exception as e:
        return None, str(e)

def cadastro_supabase(email: str, senha: str, nome: str = ""):
    try:
        payload = {"email": email, "password": senha}
        if nome.strip():
            payload["options"] = {"data": {"full_name": nome.strip()}}
        res = supabase.auth.sign_up(payload)
        if res.user:
            garantir_linha_usuario(res.user.id)
        return res.user, None
    except Exception as e:
        return None, str(e)

def _html(bloco: str) -> str:
    """Remove a indentação de cada linha antes de mandar pro st.markdown.
    Sem isso, HTML com 4+ espaços de indentação (comum em f-strings
    dentro de loops/with aninhados) é interpretado pelo parser de
    Markdown como bloco de código, e aparece como texto cru na tela."""
    return "\n".join(l.strip() for l in bloco.strip().split("\n"))

def obter_nome_usuario() -> str:
    """Nome de exibição do usuário logado. Cai pro prefixo do e-mail
    se ele ainda não tiver preenchido o nome."""
    u = st.session_state.get("user")
    if not u:
        return ""
    nome = (getattr(u, "user_metadata", None) or {}).get("full_name", "").strip()
    if nome:
        return nome
    return (u.email or "").split("@")[0]

def atualizar_nome_usuario(novo_nome: str) -> bool:
    """Atualiza o nome nos metadados do usuário no Supabase Auth."""
    try:
        res = supabase.auth.update_user({"data": {"full_name": novo_nome.strip()}})
        if res.user:
            st.session_state.user = res.user
        return True
    except Exception as e:
        st.toast(f"Erro ao atualizar nome: {e}", icon="⚠️")
        return False

def atualizar_senha_usuario(nova_senha: str) -> bool:
    """Atualiza a senha do usuário logado no Supabase Auth."""
    try:
        supabase.auth.update_user({"password": nova_senha})
        return True
    except Exception as e:
        st.toast(f"Erro ao atualizar senha: {e}", icon="⚠️")
        return False

def garantir_linha_usuario(user_id: str):
    try:
        existe = (
            supabase.table("ci_dados")
            .select("user_id")
            .eq("user_id", user_id)
            .execute()
        )
        if not existe.data:
            supabase.table("ci_dados").insert({
                "user_id": user_id,
                "minha_empresa": {},
                "concorrentes": [],
                "metricas_redes": {},
                "ads_cache": {},
                "analises_salvas": [],
                "redes_analises_salvas": [],
                "ads_analises_salvas": [],
                "seo_cache": {},
            }).execute()
    except Exception as e:
        st.toast(f"Erro ao inicializar dados: {e}", icon="⚠️")

def logout_supabase():
    try:
        supabase.auth.sign_out()
    except Exception:
        pass

