# ===================================================
# PÁGINAS
# ===================================================

# ---------------------------------------------------
# FUNÇÃO salvar_cache_ads 
# ---------------------------------------------------
 
def _imagem_precisa_de_b64_provisorio(ad: dict) -> bool:
    """True quando o anúncio é do Google Ads e a imagem AINDA não foi
    migrada pra um link permanente do R2 — nesses casos o `images_b64`
    (base64 já baixado com sucesso durante a coleta) precisa ser mantido
    no cache, porque é a ÚNICA fonte que o card consegue renderizar de
    verdade.

    Isso não é necessário pro Meta: o link cru do Facebook/Instagram
    carrega direto no <img> do navegador sem problema (a Meta não bloqueia
    hotlink de referrer vazio), então o card mostra o link original
    normalmente enquanto a migração pro R2 não termina — exatamente como
    o usuário espera que funcione.

    Já o CDN do Google (tpc.googlesyndication.com) bloqueia esse mesmo
    tipo de carregamento direto do navegador (o <img> do card usa
    referrerpolicy="no-referrer", e não dá pra forjar um Referer
    específico só de HTML/CSS) — então, sem o base64 como imagem
    provisória, o card do Google fica sem imagem nenhuma até a migração
    terminar, mesmo quando a coleta já baixou a imagem certa com
    sucesso (é exatamente o bug relatado: o backend acha e baixa a
    imagem, mas o card mostra 'Ver criativo →' até a migração rodar)."""
    imgs = ad.get("images") or []
    if not imgs:
        return False
    if not any(("googlesyndication.com" in u or "googleusercontent.com" in u) for u in imgs):
        return False  # não é imagem do Google — Meta não precisa desse fallback
    if R2_PUBLIC_BASE and all(u.startswith(R2_PUBLIC_BASE) for u in imgs):
        return False  # já migrado — não precisa mais do base64
    return True

def salvar_cache_ads(dados: dict, migrar_midia: bool = True, user_id: str = None):
    try:
        # `user_id` deve ser passado explicitamente quando essa função é
        # chamada de uma thread em background (ex: dentro da coleta de
        # anúncios) — `st.session_state` não tem contexto válido fora da
        # thread principal do Streamlit, e ler `st.session_state.user.id`
        # nesse caso falha silenciosamente (cai no except abaixo), fazendo
        # o save nunca acontecer de verdade, mesmo com a atividade sendo
        # marcada como "concluído" logo em seguida. Só cai no fallback de
        # `st.session_state` quando chamado do próprio script principal
        # (onde o contexto existe e é seguro).
        user_id = user_id or st.session_state.user.id

        dados_limpos = {}
        for empresa, entry in dados.items():
            entry_limpa = dict(entry)
            ads_limpos = [dict(ad) for ad in entry.get("data", [])]
            for ad_limpo in ads_limpos:
                ad_limpo.pop("video_thumb", None)
            entry_limpa["data"] = ads_limpos
            dados_limpos[empresa] = entry_limpa

        # Antes de persistir: troca os links do Facebook (que expiram) por
        # URLs permanentes no Cloudflare R2, respeitando a cota do plano.
        # Isolado em try/except próprio: se o pipeline de mídia falhar por
        # qualquer motivo, o save do ads_cache tem que acontecer do mesmo
        # jeito (com os links originais), nunca pode travar o essencial.
        # migrar_midia=False pula essa etapa (usado no save "rápido" logo
        # após a coleta — a migração real roda depois, em background).
        if migrar_midia:
            try:
                dados_limpos, _stats_midia = persistir_midias_de_ads(dados_limpos, user_id)
                if _stats_midia.get("nao_migrados"):
                    st.toast(
                        f"{_stats_midia['nao_migrados']} de {_stats_midia['total']} mídias não "
                        f"foram migradas pro R2 (ficaram com o link original).",
                        icon="⚠️",
                    )
            except Exception as e_midia:
                st.toast(f"Mídia não foi persistida no R2 (dados salvos normalmente): {e_midia}", icon="⚠️")

        # Só descarta o base64 depois de saber o resultado final da
        # migração (acima) — se ainda sobrou link cru do Google sem
        # migrar, o card depende desse base64 pra mostrar alguma coisa
        # (ver _imagem_precisa_de_b64_provisorio).
        for entry_limpa in dados_limpos.values():
            for ad_limpo in entry_limpa.get("data", []):
                if not _imagem_precisa_de_b64_provisorio(ad_limpo):
                    ad_limpo.pop("images_b64", None)

        supabase.table("ci_dados").update({
            "ads_cache": dados_limpos,
        }).eq("user_id", user_id).execute()
    except Exception as e:
        st.toast(f"Erro ao salvar cache de ads: {e}", icon="⚠️")

def salvar_cache_gads(dados: dict, migrar_midia: bool = True, user_id: str = None):
    """Equivalente a `salvar_cache_ads`, mas pro Google Ads — grava na
    coluna `gads_cache`, não `ads_cache`. Antes, a coleta de Google Ads
    chamava por engano a função de Meta Ads, o que fazia os anúncios do
    Google sobrescreverem o cache do Meta (e a coluna gads_cache nunca
    era realmente escrita)."""
    try:
        user_id = user_id or st.session_state.user.id

        dados_limpos = {}
        for empresa, entry in dados.items():
            entry_limpa = dict(entry)
            ads_limpos = [dict(ad) for ad in entry.get("data", [])]
            for ad_limpo in ads_limpos:
                ad_limpo.pop("video_thumb", None)
            entry_limpa["data"] = ads_limpos
            dados_limpos[empresa] = entry_limpa

        if migrar_midia:
            try:
                dados_limpos, _stats_midia = persistir_midias_de_ads(dados_limpos, user_id)
                if _stats_midia.get("nao_migrados"):
                    st.toast(
                        f"{_stats_midia['nao_migrados']} de {_stats_midia['total']} mídias não "
                        f"foram migradas pro R2 (ficaram com o link original).",
                        icon="⚠️",
                    )
            except Exception as e_midia:
                st.toast(f"Mídia não foi persistida no R2 (dados salvos normalmente): {e_midia}", icon="⚠️")

        # Só descarta o base64 depois de saber o resultado final da
        # migração (acima) — se ainda sobrou link cru do Google sem
        # migrar, o card depende desse base64 pra mostrar alguma coisa
        # (ver _imagem_precisa_de_b64_provisorio).
        for entry_limpa in dados_limpos.values():
            for ad_limpo in entry_limpa.get("data", []):
                if not _imagem_precisa_de_b64_provisorio(ad_limpo):
                    ad_limpo.pop("images_b64", None)

        supabase.table("ci_dados").update({
            "gads_cache": dados_limpos,
        }).eq("user_id", user_id).execute()
    except Exception as e:
        st.toast(f"Erro ao salvar cache de Google Ads: {e}", icon="⚠️")

# ---------------------------------------------------
#  REPROCESSAMENTO — comprimir mídias já salvas no R2
# ---------------------------------------------------
# Diferente da migração inicial, aqui NÃO precisamos do link original do
# Facebook (que pode já ter expirado) — a mídia já está no nosso próprio
# bucket, então baixamos da nossa cópia, comprimimos, subimos a versão
# nova, e atualizamos as referências (tabela midias + ads_cache).

def _comprimir_midia_existente(tipo: str, conteudo: bytes, mime_type: str):
    """Roteia pra função de compressão certa (imagem ou vídeo) de acordo
    com o tipo da mídia já salva."""
    if tipo == "video":
        return _comprimir_video(conteudo, mime_type or "video/mp4")
    return _comprimir_imagem(conteudo, mime_type or "image/jpeg")

def _reprocessar_midias_background(user_id: str, atividade_id: str):
    try:
        res = (
            supabase.table("midias")
            .select("*")
            .eq("user_id", user_id)
            .in_("tipo", ["imagem", "video"])
            .execute()
        )
        midias = res.data or []

        processadas = 0
        transcritas = 0
        economizado_bytes = 0

        for m in midias:
            try:
                url_antiga = m["url_cdn"]
                # vídeos são maiores e demoram mais pra baixar/reencodar
                # que imagens, então usamos um timeout maior pra eles.
                timeout_download = 120 if m.get("tipo") == "video" else 20
                resp = requests.get(url_antiga, timeout=timeout_download)
                resp.raise_for_status()
                conteudo_original = resp.content
                tamanho_original = len(conteudo_original)

                # transcreve vídeos que ainda não têm transcrição salva —
                # roda mesmo que a recompressão abaixo não ajude em nada
                if m.get("tipo") == "video" and not (m.get("transcricao") or "").strip():
                    transcricao_nova = _transcrever_video_whisper(conteudo_original)
                    if transcricao_nova:
                        supabase.table("midias").update(
                            {"transcricao": transcricao_nova}
                        ).eq("id", m["id"]).execute()
                        transcritas += 1

                conteudo_novo, content_type_novo, ext_novo = _comprimir_midia_existente(
                    m.get("tipo"), conteudo_original, m.get("mime_type")
                )
                if not ext_novo or len(conteudo_novo) >= tamanho_original:
                    continue  # já estava no formato/tamanho ótimo, ou comprimir não ajudou nesse caso

                nova_key = m["storage_key"].rsplit(".", 1)[0] + ext_novo
                r2_client.put_object(
                    Bucket=R2_BUCKET, Key=nova_key, Body=conteudo_novo, ContentType=content_type_novo,
                )
                url_nova = f"{R2_PUBLIC_BASE}/{nova_key}"

                supabase.table("midias").update({
                    "storage_key":   nova_key,
                    "url_cdn":       url_nova,
                    "mime_type":     content_type_novo,
                    "tamanho_bytes": len(conteudo_novo),
                }).eq("id", m["id"]).execute()

                if nova_key != m["storage_key"]:
                    try:
                        r2_client.delete_object(Bucket=R2_BUCKET, Key=m["storage_key"])
                    except Exception:
                        pass

                # atualiza as referências no ads_cache — troca atômica
                # via RPC no Postgres, sem ler-e-regravar o blob inteiro
                # em Python (evita corrida com outras migrações/coletas
                # rodando ao mesmo tempo, mesmo com o reprocessamento
                # levando bastante tempo pra terminar todos os itens).
                supabase.rpc("substituir_url_no_ads_cache", {
                    "p_user_id": user_id,
                    "p_url_antiga": url_antiga,
                    "p_url_nova": url_nova,
                }).execute()

                processadas += 1
                economizado_bytes += (tamanho_original - len(conteudo_novo))
            except Exception:
                continue

        economizado_mb = round(economizado_bytes / (1024 * 1024), 1)
        atualizar_atividade(atividade_id, "concluido", {
            "processadas": processadas,
            "transcritas": transcritas,
            "total": len(midias),
            "economizado_mb": economizado_mb,
        })
    except Exception as e:
        atualizar_atividade(atividade_id, "erro", {"motivo": str(e)})

def iniciar_reprocessamento_midia_background(user_id: str):
    """Roda o reprocessamento de todas as mídias já salvas do usuário,
    sem travar a página. Acompanhe o resultado no sino de notificações."""
    atividade_id = criar_atividade(
        user_id, "reprocessamento_midia", "Otimizando espaço da Biblioteca de Arquivos Permanente", {}
    )
    threading.Thread(
        target=_reprocessar_midias_background,
        args=(user_id, atividade_id),
        daemon=True,
    ).start()


# ---------------------------------------------------
#  RECONCILIAÇÃO — reconecta mídias já migradas que ficaram órfãs
# ---------------------------------------------------
# Corrige retroativamente o caso de mídias que já foram baixadas pro R2
# (existem na tabela `midias`, com url_origem -> url_cdn mapeados) mas
# cujo ads_cache ainda aponta pro link original — por causa da corrida
# de concorrência que existia antes da correção via RPC atômica. Não
# precisa coletar de novo: só usa o mapeamento que já está salvo.

def _reconciliar_midia_background(user_id: str, atividade_id: str):
    try:
        res = supabase.table("midias").select("url_origem, url_cdn").eq("user_id", user_id).execute()
        mapeamento = res.data or []

        corrigidos = 0
        for m in mapeamento:
            url_origem = m.get("url_origem")
            url_cdn = m.get("url_cdn")
            if not url_origem or not url_cdn or url_origem == url_cdn:
                continue
            try:
                resultado = supabase.rpc(_rpc_substituir_url_cache(_plataforma_da_url(url_origem)), {
                    "p_user_id": user_id,
                    "p_url_antiga": url_origem,
                    "p_url_nova": url_cdn,
                }).execute()
                if resultado.data:
                    corrigidos += 1
            except Exception:
                continue

        atualizar_atividade(atividade_id, "concluido", {
            "verificados": len(mapeamento),
            "corrigidos": corrigidos,
        })
    except Exception as e:
        atualizar_atividade(atividade_id, "erro", {"motivo": str(e)})

def iniciar_reconciliacao_midia_background(user_id: str):
    """Reconecta mídias já migradas pro R2 que ficaram com a referência
    antiga no ads_cache. Roda em background — acompanhe no sino."""
    atividade_id = criar_atividade(
        user_id, "reconciliacao_midia", "Reconectando anúncios já salvos na Biblioteca de Arquivos Permanente", {}
    )
    threading.Thread(
        target=_reconciliar_midia_background,
        args=(user_id, atividade_id),
        daemon=True,
    ).start()


# ---------------------------------------------------
#  RETENTATIVA — mídias que falharam no download (registradas por ad_id)
# ---------------------------------------------------
# Toda vez que baixar_e_persistir_midia falha (rede instável, Facebook
# derrubando a conexão, etc.) o anúncio fica registrado em
# `midias_falhas` com o ad_id, a empresa e quantas vezes já tentamos.
# Essa rotina varre esses registros e tenta baixar de novo — só os que
# ainda não bateram no teto de MAX_TENTATIVAS_MIDIA. É isso que garante
# que "sempre tem a opção de baixar o vídeo": em vez do card ficar pra
# sempre com o link original do Facebook na primeira falha, ele volta a
# ser tentado nas próximas coletas até dar certo ou esgotar o limite.

def _tentar_novamente_midias_background(user_id: str, atividade_id: str = None):
    try:
        res = (
            supabase.table("midias_falhas")
            .select("*")
            .eq("user_id", user_id)
            .lt("tentativas", MAX_TENTATIVAS_MIDIA)
            .execute()
        )
        pendentes = res.data or []
        if not pendentes:
            atualizar_atividade(atividade_id, "concluido", {"motivo": "nenhuma mídia pendente de retentativa"})
            return

        recuperadas = 0
        esgotadas_google = 0
        esgotadas_meta = 0
        for f in pendentes:
            url_antiga = f["url_origem"]
            nova_url = baixar_e_persistir_midia(
                url_antiga, user_id, f["empresa"], f.get("tipo", "imagem"), f.get("ad_id")
            )
            if nova_url == url_antiga:
                # continua falhando — baixar_e_persistir_midia já incrementou a
                # tentativa. Se essa foi a última chance (teto atingido), conta
                # aqui pra reportar de forma visível no card da atividade —
                # antes isso ficava mudo: o card fechava como "concluído" sem
                # nenhum aviso, e a mídia ficava pra sempre com o selo de
                # relógio (link não permanente) sem o usuário saber que já
                # esgotamos as tentativas.
                _tentativas_agora = (f.get("tentativas", 0) or 0) + 1
                if _tentativas_agora >= MAX_TENTATIVAS_MIDIA:
                    if "googlesyndication.com" in url_antiga or "googleusercontent.com" in url_antiga:
                        esgotadas_google += 1
                    else:
                        esgotadas_meta += 1
                continue

            # sucesso: baixar_e_persistir_midia já limpou o registro de
            # falha; falta só apontar o ads_cache pra URL nova no R2.
            try:
                supabase.rpc(_rpc_substituir_url_cache(_plataforma_da_url(url_antiga)), {
                    "p_user_id": user_id,
                    "p_url_antiga": url_antiga,
                    "p_url_nova": nova_url,
                }).execute()
                recuperadas += 1
            except Exception:
                pass

        _detalhes_final = {
            "verificadas": len(pendentes),
            "recuperadas": recuperadas,
        }
        _avisos = []
        if esgotadas_google:
            _avisos.append(
                f"{esgotadas_google} imagem(ns)/vídeo(s) do Google Ads não puderam ser salvos "
                f"permanentemente após {MAX_TENTATIVAS_MIDIA} tentativas — o CDN do Google "
                f"bloqueou o download. Continuam com o link original (selo de relógio no card)."
            )
        if esgotadas_meta:
            _avisos.append(
                f"{esgotadas_meta} mídia(s) do Meta Ads não puderam ser salvas permanentemente "
                f"após {MAX_TENTATIVAS_MIDIA} tentativas."
            )
        if _avisos:
            _detalhes_final["aviso"] = " ".join(_avisos)
            atualizar_atividade(atividade_id, "concluido_com_erro", _detalhes_final)
        else:
            atualizar_atividade(atividade_id, "concluido", _detalhes_final)
    except Exception as e:
        atualizar_atividade(atividade_id, "erro", {"motivo": str(e)})

def iniciar_retentativa_midias_background(user_id: str):
    """Tenta baixar de novo as mídias que falharam antes (respeitando o
    teto de MAX_TENTATIVAS_MIDIA por mídia). Roda em background —
    acompanhe o resultado no sino de notificações. Chamado tanto
    automaticamente (a cada nova coleta) quanto manualmente pelo botão
    na aba de perfil."""
    atividade_id = criar_atividade(
        user_id, "retentativa_midia", "Tentando salvar anúncios pendentes na Biblioteca de Arquivos Permanente", {}
    )
    threading.Thread(
        target=_tentar_novamente_midias_background,
        args=(user_id, atividade_id),
        daemon=True,
    ).start()

def contar_midias_pendentes_retentativa(user_id: str) -> int:
    """Quantas mídias ainda têm chance de retentativa (não esgotaram o
    teto) — usado pra mostrar no botão da aba de perfil."""
    try:
        res = (
            supabase.table("midias_falhas")
            .select("id", count="exact")
            .eq("user_id", user_id)
            .lt("tentativas", MAX_TENTATIVAS_MIDIA)
            .execute()
        )
        return res.count or 0
    except Exception:
        return 0


# ---------------------------------------------------
#  VARREDURA GERAL — migra mídia pendente em TODOS os anúncios salvos
# ---------------------------------------------------
# A retentativa acima só age sobre mídia que já passou por uma tentativa
# registrada em `midias_falhas`. Isso deixa de fora anúncios antigos,
# coletados antes desse sistema existir (ou numa época em que a cota do
# plano ou o R2 não permitiam o download) — a mídia nunca chegou a
# "falhar" de um jeito que gerasse registro, só nunca foi tentada. Essa
# varredura resolve esse caso: relê o ads_cache inteiro do banco e tenta
# migrar qualquer imagem/vídeo que ainda esteja com o link original,
# empresa por empresa (mesmo padrão sequencial da migração normal, pra
# não esgotar processos do SO com vários vídeos ao mesmo tempo).

def _migrar_pendentes_geral_background(user_id: str, atividade_id: str = None):
    try:
        res = supabase.table("ci_dados").select("ads_cache").eq("user_id", user_id).execute()
        if not res.data:
            atualizar_atividade(atividade_id, "erro", {"motivo": "ci_dados não encontrado"})
            return
        ads_cache = res.data[0].get("ads_cache") or {}

        def _e_r2(u):
            return bool(u) and bool(R2_PUBLIC_BASE) and u.startswith(R2_PUBLIC_BASE)

        pendentes_antes = sum(
            1
            for entry in ads_cache.values()
            for ad in entry.get("data", [])
            for u in (ad.get("images") or []) + (ad.get("videos") or [])
            if u and not _e_r2(u)
        )
        if pendentes_antes == 0:
            atualizar_atividade(atividade_id, "concluido", {"motivo": "todos os anúncios já estão com mídia migrada"})
            return

        from concurrent.futures import ThreadPoolExecutor as _TPE, TimeoutError as _TimeoutErr

        verificadas_total, ainda_pendentes_total = 0, 0
        _log_com_erro_geral = []   # acumula entre empresas, com prefixo da empresa no título
        _log_migrados_geral = []
        LIMITE_AMOSTRA_LOG_GERAL = 30
        for empresa, entry in ads_cache.items():
            n_pendentes_empresa = sum(
                1 for ad in entry.get("data", []) for u in (ad.get("images") or []) + (ad.get("videos") or [])
                if u and not _e_r2(u)
            )
            if n_pendentes_empresa == 0:
                continue  # essa empresa já está tudo migrado — pula sem gastar tempo

            limite_segundos = _estimar_timeout_migracao(entry)
            with _TPE(max_workers=1) as executor:
                future = executor.submit(persistir_midias_de_ads, {empresa: entry}, user_id)
                try:
                    migrado, stats = future.result(timeout=limite_segundos)
                except _TimeoutErr:
                    ainda_pendentes_total += n_pendentes_empresa
                    continue
                except Exception:
                    ainda_pendentes_total += n_pendentes_empresa
                    continue

            atualizacoes = {
                str(ad["id"]): ad for ad in migrado.get(empresa, {}).get("data", []) if ad.get("id")
            }
            if atualizacoes:
                try:
                    supabase.rpc("atualizar_ads_no_cache", {
                        "p_user_id": user_id,
                        "p_empresa": empresa,
                        "p_atualizacoes": atualizacoes,
                    }).execute()
                except Exception:
                    pass

            verificadas_total += stats.get("total", 0)
            ainda_pendentes_total += stats.get("nao_migrados", 0)
            # Empresa vai junto no título aqui porque a varredura geral mistura
            # várias empresas numa atividade só — sem isso, "mais informações"
            # mostraria uma lista de anúncios sem dizer de qual empresa é cada um.
            if len(_log_com_erro_geral) < LIMITE_AMOSTRA_LOG_GERAL:
                for a in stats.get("anuncios_com_erro", []):
                    if len(_log_com_erro_geral) >= LIMITE_AMOSTRA_LOG_GERAL:
                        break
                    _log_com_erro_geral.append({"id": a["id"], "titulo": f"{a['titulo']} ({empresa})"})
            if len(_log_migrados_geral) < LIMITE_AMOSTRA_LOG_GERAL:
                for a in stats.get("anuncios_migrados", []):
                    if len(_log_migrados_geral) >= LIMITE_AMOSTRA_LOG_GERAL:
                        break
                    _log_migrados_geral.append({"id": a["id"], "titulo": f"{a['titulo']} ({empresa})"})

        # Mesma regra da migração pontual: só é "concluido" se não sobrou
        # nenhum anúncio pendente. Sobrando algum, fica "em_andamento" com
        # o progresso visível, em vez de fechar como sucesso escondendo o
        # que ainda falta migrar.
        #
        # Mesma ressalva da migração pontual (ver _migrar_midia_background):
        # se o motivo de sobrar pendente é a cota mensal ter estourado, não
        # existe "vamos tentar de novo automaticamente" de verdade — fecha
        # como cota esgotada em vez de prometer um retry que não vai rodar.
        if ainda_pendentes_total and not pode_baixar_midia(user_id):
            _limite_cota = PLANOS_QUOTA_MIDIAS.get(obter_plano_usuario())
            atualizar_atividade(atividade_id, "erro", {
                "migradas": verificadas_total - ainda_pendentes_total,
                "total": verificadas_total,
                "cota_esgotada": True,
                "motivo": (
                    f"{ainda_pendentes_total} anúncios ainda não foram migrados porque a cota "
                    f"mensal de anúncios com mídia do seu plano "
                    f"({_limite_cota if _limite_cota is not None else '∞'}/mês) foi atingida. "
                    f"Isso não é uma falha passageira — a migração retoma no início do "
                    f"próximo ciclo ou assim que o plano for atualizado."
                ),
                "anuncios_com_erro": _log_com_erro_geral,
                "anuncios_migrados": _log_migrados_geral,
            })
        elif ainda_pendentes_total:
            atualizar_atividade(atividade_id, "em_andamento", {
                "migradas": verificadas_total - ainda_pendentes_total,
                "total": verificadas_total,
                "aviso": (
                    f"{verificadas_total - ainda_pendentes_total} de {verificadas_total} salvos na "
                    f"Biblioteca de Arquivos Permanente — {ainda_pendentes_total} ainda pendentes "
                    f"(vamos tentar de novo automaticamente)"
                ),
                "anuncios_com_erro": _log_com_erro_geral,
                "anuncios_migrados": _log_migrados_geral,
            })
        else:
            atualizar_atividade(atividade_id, "concluido", {
                "pendentes_antes": pendentes_antes,
                "verificadas": verificadas_total,
                "ainda_pendentes_depois": 0,
                "anuncios_migrados": _log_migrados_geral,
            })
    except Exception as e:
        atualizar_atividade(atividade_id, "erro", {"motivo": str(e)})

def iniciar_migracao_pendente_geral_background(user_id: str):
    """Varre todos os anúncios já salvos (de todas as empresas) e migra
    pro R2 qualquer mídia que ainda esteja com o link original da Meta —
    inclusive anúncios antigos que nunca chegaram a ter uma tentativa
    registrada. Roda em background — acompanhe no sino de notificações."""
    atividade_id = criar_atividade(
        user_id, "migracao_midia", "Varredura geral: migrar mídias pendentes de todos os anúncios", {}
    )
    threading.Thread(
        target=_migrar_pendentes_geral_background,
        args=(user_id, atividade_id),
        daemon=True,
    ).start()



# ---------------------------------------------------
# HOME — Pagina - Minha Empresa
# ---------------------------------------------------

# ── Coleta de perfis do Instagram via RapidAPI ──────────────────────
# Movido para escopo de módulo (antes vivia só dentro do bloco da
# página "redes") pra poder ser reutilizado pelo botão "Tentar
# novamente" das notificações (refazer_coleta_redes, abaixo), que
# roda a partir da página "notificacoes" — um escopo totalmente
# separado do bloco onde essas funções viviam antes.
def _rapidapi_get_com_retry(url: str, headers: dict, tentativas: int = 3, timeout: int = 20):
    """GET com retry + backoff pra aguentar instabilidade da API do
    RapidAPI (timeouts pontuais são comuns em horários de pico).
    Levanta a última exceção se todas as tentativas falharem."""
    import time
    ultimo_erro = None
    for i in range(tentativas):
        try:
            return requests.get(url, headers=headers, timeout=timeout)
        except requests.exceptions.RequestException as e:
            ultimo_erro = e
            if i < tentativas - 1:
                time.sleep(1.5 * (i + 1))  # backoff: 1.5s, 3s
    raise ultimo_erro

def _coletar_rapidapi_sem_cache(handle: str) -> dict:
    handle_limpo = handle.lstrip("@").strip()
    if not handle_limpo:
        return {"erro": "Handle vazio"}
    try:
        rapidapi_key = st.secrets.get("RAPIDAPI_KEY", "")
        if not rapidapi_key:
            return {"erro": "RAPIDAPI_KEY não configurada"}

        headers = {
            "x-rapidapi-key": rapidapi_key,
            "x-rapidapi-host": "instagram-looter2.p.rapidapi.com",
        }

        try:
            r = _rapidapi_get_com_retry(
                f"https://instagram-looter2.p.rapidapi.com/profile2?username={handle_limpo}",
                headers=headers,
            )
        except requests.exceptions.Timeout:
            return {"erro": "A API do Instagram demorou demais pra responder (timeout). Tenta de novo em instantes."}
        except requests.exceptions.RequestException as e:
            return {"erro": f"Falha ao conectar na API do Instagram: {e}"}
        data = r.json()
        user_data = data
        if isinstance(data, dict):
            if "data" in data:   user_data = data["data"]
            elif "user" in data: user_data = data["user"]

        if not user_data or user_data.get("status") is False or "message" in user_data or "errorMessage" in user_data:
            _msg_erro_rapidapi = (
                user_data.get("errorMessage")
                or user_data.get("message")
                or "Perfil não encontrado"
            ) if isinstance(user_data, dict) else "Perfil não encontrado"
            return {"erro": _msg_erro_rapidapi}

        seg         = int(user_data.get("follower_count") or user_data.get("edge_followed_by", {}).get("count") or 0)
        total_posts = int(user_data.get("media_count") or user_data.get("edge_owner_to_timeline_media", {}).get("count") or 0)
        pk          = str(user_data.get("pk") or user_data.get("id") or "").strip()

        posts_data = []
        if pk:
            for endpoint in [
                f"https://instagram-looter2.p.rapidapi.com/user-feeds?id={pk}&count=12&allow_restricted_media=false",
                f"https://instagram-looter2.p.rapidapi.com/user-medias?id={pk}&count=12",
            ]:
                try:
                    rp    = _rapidapi_get_com_retry(endpoint, headers=headers)
                    pr    = rp.json()
                    items = pr if isinstance(pr, list) else pr.get("items", [])
                    if items:
                        for p in items[:12]:
                            likes    = int(p.get("like_count") or 0)
                            comments = int(p.get("comment_count") or 0)

                            thumb = ""
                            thumb_hd = ""
                            if p.get("image_versions2"):
                                cands = p["image_versions2"].get("candidates", [])
                                if cands:
                                    cands_sorted = sorted(cands, key=lambda c: c.get("width", 0), reverse=True)
                                    thumb_hd = cands_sorted[0].get("url", "")
                                    thumb = cands_sorted[-1].get("url", "")
                                    if len(cands_sorted) == 1:
                                        thumb = thumb_hd
                                else:
                                    thumb_hd = ""
                                    thumb = ""

                            if not thumb_hd:
                                thumb_hd = (
                                    p.get("display_url")
                                    or p.get("thumbnail_src")
                                    or p.get("image_url")
                                    or ""
                                )

                            if p.get("display_resources"):
                                resources = sorted(
                                    p["display_resources"],
                                    key=lambda r: r.get("config_width", 0),
                                    reverse=True
                                )
                                if resources:
                                    thumb_hd = resources[0].get("src", "") or thumb_hd

                            if not thumb_hd:
                                thumb_hd = thumb

                            if not thumb:
                                thumb = thumb_hd

                            if p.get("thumbnail_url") and not thumb:
                                thumb = p["thumbnail_url"]
                                if not thumb_hd:
                                    thumb_hd = thumb

                            caption  = ""
                            if p.get("caption"):
                                caption = (
                                    p["caption"].get("text", "")
                                    if isinstance(p["caption"], dict)
                                    else str(p["caption"])
                                )[:500]
                            taken_at = p.get("taken_at", 0)
                            date_str = ""
                            if taken_at:
                                try:
                                    date_str = datetime.datetime.fromtimestamp(taken_at).strftime("%d/%m/%Y")
                                except Exception:
                                    pass
                            shortcode = p.get("code") or p.get("shortcode") or ""
                            post_url  = f"https://www.instagram.com/p/{shortcode}/" if shortcode else ""

                            media_type = p.get("media_type", 1)
                            is_reel = media_type == 2

                            video_url = ""
                            if is_reel:
                                video_url = (
                                    p.get("video_url")
                                    or (p.get("video_versions") or [{}])[0].get("url", "")
                                    or ""
                                )

                            carousel_imgs = []
                            carousel_imgs_hd = []

                            if media_type == 8:
                                for slide in (p.get("carousel_media") or []):
                                    cands = slide.get("image_versions2", {}).get("candidates", [])
                                    url_hd     = cands[0].get("url", "") if cands else ""
                                    url_thumb  = cands[-1].get("url", "") if cands else url_hd
                                    url_display = slide.get("display_uri", "")

                                    escolhida_hd    = url_hd or url_display
                                    escolhida_thumb = url_thumb or url_display or url_hd

                                    if escolhida_hd:
                                        carousel_imgs_hd.append(escolhida_hd)
                                    if escolhida_thumb:
                                        carousel_imgs.append(escolhida_thumb)

                                if not carousel_imgs and thumb:
                                    carousel_imgs = [thumb]
                                if not carousel_imgs_hd and thumb_hd:
                                    carousel_imgs_hd = [thumb_hd]

                            posts_data.append({
                                "likes":          likes,
                                "comments":       comments,
                                "thumb":          thumb,
                                "thumb_hd":       thumb_hd,
                                "display_url":    p.get("display_url") or p.get("thumbnail_src") or p.get("image_url") or thumb_hd,
                                "caption":        caption,
                                "date":           date_str,
                                "is_video":       is_reel,
                                "media_type":     media_type,
                                "video_url":      video_url,
                                "post_url":       post_url,
                                "shortcode":      shortcode,
                                "carousel_imgs":  carousel_imgs,
                                "carousel_imgs_hd": carousel_imgs_hd,
                                "_raw": {
                                    k: v for k, v in p.items()
                                    if k not in ("carousel_media", "video_versions", "image_versions2")
                                },
                                "_raw_image_versions2": {
                                    "candidates": [
                                        {"width": c.get("width"), "height": c.get("height"), "url": c.get("url", "")[:80] + "..."}
                                        for c in (p.get("image_versions2") or {}).get("candidates", [])
                                    ]
                                },
                                "_raw_display_resources": p.get("display_resources", []),
                            })
                        break
                except Exception:
                    continue

        # Guarda contra "sucesso fantasma": a API às vezes responde 200
        # com um perfil válido mas sem follower_count/media_count e sem
        # nenhum post (perfil privado, endpoint instável, etc). Sem essa
        # checagem isso virava um resultado "ok" com seguidores=0 e
        # posts=0 — a atividade "Coleta de redes sociais" marcava
        # Concluído e listava o perfil como coletado com sucesso, mas na
        # prática nenhum dado real chegou (perfil ficava com 0/0 e "Sem
        # postagens disponíveis" na tela). Agora isso conta como erro,
        # pra notificação refletir a realidade e o usuário saber que
        # precisa tentar coletar de novo.
        # /profile2 não traz mais media_count (sempre vem null) — como
        # fallback, usa a quantidade de posts que realmente vieram na
        # coleta em vez de deixar o total zerado (ficaria enganoso na UI).
        if total_posts == 0 and posts_data:
            total_posts = len(posts_data)

        if seg == 0 and total_posts == 0 and not posts_data:
            return {"erro": "A API não retornou dados para este perfil (perfil privado, incorreto ou instabilidade momentânea). Tente coletar novamente."}

        if posts_data:
            eng_medio = sum(p["likes"] + p["comments"] for p in posts_data) / len(posts_data)
            eng_pct   = round(eng_medio / seg * 100, 2) if seg > 0 else 0.0
        else:
            eng_pct   = 3.0 if seg <= 10_000 else (2.0 if seg <= 50_000 else (1.5 if seg <= 100_000 else 1.0))
            eng_medio = round(seg * eng_pct / 100, 1)

        _profile_pic_raw = (
            user_data.get("profile_pic_url_hd")
            or user_data.get("profile_pic_url")
            or user_data.get("hd_profile_pic_url_info", {}).get("url", "")
            or ""
        )

        if not _profile_pic_raw and posts_data:
            try:
                raw = posts_data[0].get("_raw", {})
                _profile_pic_raw = (
                    raw.get("user", {}).get("profile_pic_url_hd", "")
                    or raw.get("user", {}).get("profile_pic_url", "")
                    or raw.get("caption", {}).get("user", {}).get("profile_pic_url_hd", "")
                    or raw.get("caption", {}).get("user", {}).get("profile_pic_url", "")
                    or ""
                )
            except Exception:
                pass

        profile_pic = _profile_pic_raw

        if profile_pic:
            try:
                import requests as _req
                import base64 as _b64
                _r = _req.get(profile_pic, timeout=8, headers={"User-Agent": "Mozilla/5.0"})
                if _r.status_code == 200:
                    _mime = _r.headers.get("content-type", "image/jpeg").split(";")[0]
                    profile_pic = f"data:{_mime};base64,{_b64.b64encode(_r.content).decode()}"
            except Exception:
                pass

        _bio_links = user_data.get("bio_links") or []
        _all_urls = [
            link.get("url", "") for link in _bio_links if link.get("url", "")
        ]
        if not _all_urls and user_data.get("external_url"):
            _all_urls = [user_data["external_url"]]
        _external_url = " | ".join(_all_urls)

        return {
            "handle":       "@" + handle_limpo,
            "nome_exibido": user_data.get("full_name") or user_data.get("username", handle_limpo),
            "seguidores":   seg,
            "seguindo":     int(user_data.get("following_count") or 0),
            "total_posts":  total_posts,
            "bio":          (user_data.get("biography") or ""),
            "external_url": _external_url,
            "is_verified":  user_data.get("is_verified", False),
            "eng_medio":    round(eng_medio, 1),
            "eng_pct":      eng_pct,
            "posts":        posts_data,
            "fonte":        "rapidapi",
            "erro":         None,
            "profile_pic":  profile_pic,
        }
    except Exception as e:
        return {"erro": str(e)}

_RAPIDAPI_CACHE_TTL = 1800  # 30 min

def coletar_rapidapi(handle: str) -> dict:
    # Cache manual por handle em session_state (em vez de
    # @st.cache_data) de propósito: só grava no cache quando a
    # coleta dá certo (erro is None). Assim, um timeout pontual da
    # RapidAPI não fica "preso" no cache por 30 min pro mesmo
    # handle — e, diferente de um @st.cache_data.clear() global,
    # isso não afeta o cache de outros handles já coletados com
    # sucesso.
    import time
    cache = st.session_state.setdefault("_cache_rapidapi", {})
    agora = time.time()
    entrada = cache.get(handle)
    if entrada and (agora - entrada["ts"]) < _RAPIDAPI_CACHE_TTL:
        return entrada["dados"]

    resultado = _coletar_rapidapi_sem_cache(handle)
    if not resultado.get("erro"):
        cache[handle] = {"ts": agora, "dados": resultado}
    return resultado


