        label_sites_ativo = labels_sites_map.get(subtab_sites, "")

        def _md_to_html_sites(txt):
            if not txt: return ""
            import re as _re

            txt = txt.replace("&", "&amp;")
            txt = _re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', txt)
            txt = _re.sub(r'^### (.+)$', r'<h3>\1</h3>', txt, flags=_re.MULTILINE)
            txt = _re.sub(r'^## (.+)$',  r'<h2>\1</h2>', txt, flags=_re.MULTILINE)
            txt = _re.sub(r'^# (.+)$',   r'<h1>\1</h1>', txt, flags=_re.MULTILINE)
            txt = _re.sub(r'^---+$', '<hr>', txt, flags=_re.MULTILINE)

            def _apply_inline(s):
                return _re.sub(r'\*([^*\n]+?)\*', r'<em>\1</em>', s)

            def _get_ol_match(line):
                return _re.match(r'^(\s*)(\d+)\.\s+(.*)', line)

            def _get_ul_match(line):
                return _re.match(r'^(\s*)[\*\-]\s+(.*)', line)

            lines = txt.split('\n')
            output = []
            list_stack = []

            def close_until(target_indent):
                while list_stack and list_stack[-1][1] >= target_indent:
                    tag, _ = list_stack.pop()
                    output.append(f'</{tag}>')

            def close_all():
                while list_stack:
                    tag, _ = list_stack.pop()
                    output.append(f'</{tag}>')

            i = 0
            while i < len(lines):
                line = lines[i]
                if not line.strip():
                    i += 1
                    continue
                stripped = line.strip()
                if _re.match(r'^\s*<(h[123]|hr)', line):
                    close_all()
                    output.append(stripped)
                    i += 1
                    continue
                m_ol = _get_ol_match(line)
                if m_ol:
                    item_indent = len(m_ol.group(1))
                    content     = _apply_inline(m_ol.group(3))
                    close_until(item_indent + 1)
                    if not list_stack or list_stack[-1][1] < item_indent or list_stack[-1][0] != 'ol':
                        if list_stack and list_stack[-1][1] == item_indent and list_stack[-1][0] != 'ol':
                            tag, _ = list_stack.pop()
                            output.append(f'</{tag}>')
                        output.append('<ol>')
                        list_stack.append(('ol', item_indent))
                    output.append(f'<li>{content}</li>')
                    i += 1
                    continue
                m_ul = _get_ul_match(line)
                if m_ul:
                    item_indent = len(m_ul.group(1))
                    content     = _apply_inline(m_ul.group(2))
                    close_until(item_indent + 1)
                    if not list_stack or list_stack[-1][1] < item_indent or list_stack[-1][0] != 'ul':
                        if list_stack and list_stack[-1][1] == item_indent and list_stack[-1][0] != 'ul':
                            tag, _ = list_stack.pop()
                            output.append(f'</{tag}>')
                        output.append('<ul>')
                        list_stack.append(('ul', item_indent))
                    output.append(f'<li>{content}</li>')
                    i += 1
                    continue
                close_all()
                output.append(f'<p>{_apply_inline(stripped)}</p>')
                i += 1

            close_all()
            html = '\n'.join(output)

            def _get_icon_for_title(title_clean):
                t = title_clean.lower()
                if _re.search(r'\bvs\.?\b', t):
                    return ICON_SVG['scale'], '#e0e7ff'
                if any(w in t for w in ['proposta', 'visão', 'missão', 'sobre', 'panorama', 'resumo', 'geral', 'identidade']):
                    return ICON_SVG['target'], '#dbeafe'
                if any(w in t for w in ['posicionamento', 'público', 'publico', 'persona', 'segmento', 'nicho', 'audiência', 'audiencia']):
                    return ICON_SVG['compass'], '#ede9fe'
                if any(w in t for w in ['forte', 'força', 'positivo', 'destaque', 'funciona', 'qualidade', 'diferenc']):
                    return ICON_SVG['star'], '#ccfbf1'
                if any(w in t for w in ['melhor', 'aten', 'fraquez', 'vulnerab', 'gap', 'limita', 'inconsist']):
                    return ICON_SVG['lightbulb'], '#fef3c7'
                if any(w in t for w in ['oportunidade', 'estratégia', 'estrategia', 'crescimento', 'potencial']):
                    return ICON_SVG['rocket'], '#e0f2fe'
                if any(w in t for w in ['mensage', 'métrica', 'metrica', 'desempenho', 'resultado', 'performance', 'seo', 'tráfego', 'trafego', 'serviço', 'produto', 'conteúdo', 'conteudo', 'tom de voz']):
                    return ICON_SVG['chart'], '#e2e8f0'
                if any(w in t for w in ['compara', 'concorrente', 'mercado', 'benchmark']):
                    return ICON_SVG['trophy'], '#fef9c3'
                if any(w in t for w in ['recomenda', 'ações', 'próximos', 'plano', 'sugest', 'exemplo']):
                    return ICON_SVG['clipboard'], '#f1f5f9'
                return ICON_SVG['clipboard'], '#f1f5f9'

            def _get_title_color(title_clean):
                t = title_clean.lower()
                if _re.search(r'\bvs\.?\b', t):
                    return '#4338ca'
                if any(w in t for w in ['proposta', 'visão', 'missão', 'sobre', 'panorama', 'resumo', 'geral', 'identidade']):
                    return '#1d4ed8'
                if any(w in t for w in ['posicionamento', 'público', 'publico', 'persona', 'segmento', 'nicho', 'audiência', 'audiencia']):
                    return '#6d28d9'
                if any(w in t for w in ['forte', 'força', 'positivo', 'destaque', 'funciona', 'qualidade', 'diferenc']):
                    return '#0f766e'
                if any(w in t for w in ['melhor', 'aten', 'fraquez', 'vulnerab', 'gap', 'limita', 'inconsist']):
                    return '#b45309'
                if any(w in t for w in ['oportunidade', 'estratégia', 'estrategia', 'crescimento', 'potencial']):
                    return '#0369a1'
                if any(w in t for w in ['mensage', 'métrica', 'metrica', 'desempenho', 'resultado', 'performance', 'seo', 'tráfego', 'trafego', 'serviço', 'produto', 'conteúdo', 'conteudo', 'tom de voz']):
                    return '#334155'
                if any(w in t for w in ['compara', 'concorrente', 'mercado', 'benchmark']):
                    return '#a16207'
                if any(w in t for w in ['recomenda', 'ações', 'próximos', 'plano', 'sugest', 'exemplo']):
                    return '#475569'
                return '#475569'

            def _wrap_section(html_str):
                import re as _r2

                # remove <hr> isolados (vêm dos "---" do markdown entre seções) —
                # a separação visual já é feita pelos cards/banners.
                html_str = _r2.sub(r'<hr\s*/?>', '', html_str)

                _EMOJI_RE = _r2.compile(
                    "["
                    "\U0001F1E6-\U0001FAFF"
                    "\U00002600-\U000027BF"
                    "\U00002190-\U000021FF"
                    "\U00002B00-\U00002BFF"
                    "\uFE0F\u200d\u2022"
                    "]+",
                    flags=_r2.UNICODE
                )

                def _limpar_titulo(hdr_txt):
                    # remove tags HTML remanescentes
                    limpo = _r2.sub(r'<[^>]+>', '', hdr_txt)
                    # remove emojis/pictogramas — o ícone já aparece à esquerda do card
                    limpo = _EMOJI_RE.sub('', limpo)
                    # remove espaços/pontuação que ficam sobrando após remover o emoji
                    limpo = _r2.sub(r'^[\s:\-–—]+', '', limpo)
                    return limpo.strip()

                def _make_card(hdr_txt_clean, conteudo):
                    icon_svg, icon_bg = _get_icon_for_title(hdr_txt_clean)
                    title_color = _get_title_color(hdr_txt_clean)
                    return (
                        f'<div class="sec-card">'
                        f'  <div class="sec-icon-wrap" style="background:{icon_bg};color:{title_color};">{icon_svg}</div>'
                        f'  <div class="sec-body">'
                        f'    <div class="sec-title" style="color:{title_color};">{hdr_txt_clean.upper()}</div>'
                        f'    <div class="sec-divider" style="background:{title_color}33;"></div>'
                        f'    <div class="sec-content">{conteudo}</div>'
                        f'  </div>'
                        f'</div>'
                    )

                def _make_banner(hdr_txt_clean):
                    icon_svg, icon_bg = _get_icon_for_title(hdr_txt_clean)
                    title_color = _get_title_color(hdr_txt_clean)
                    return (
                        f'<div class="sec-banner">'
                        f'  <div class="sec-banner-icon" style="background:{icon_bg};color:{title_color};">{icon_svg}</div>'
                        f'  <span class="sec-banner-text">{hdr_txt_clean}</span>'
                        f'</div>'
                    )

                def _make_plain_card(conteudo):
                    # usado para conteúdo solto sob um h2 (ex.: parágrafo de abertura,
                    # lista de recomendações) — sem repetir o título, que já está no banner.
                    return (
                        f'<div class="sec-card sec-plain">'
                        f'  <div class="sec-content">{conteudo}</div>'
                        f'</div>'
                    )

                def _make_compare_card(hdr_txt_clean, conteudo, role):
                    if role == 'own':
                        icon_bg, title_color = '#dbeafe', '#1d4ed8'
                    else:
                        icon_bg, title_color = '#f1f5f9', '#475569'
                    icon_svg, _ = _get_icon_for_title(hdr_txt_clean)
                    return (
                        f'<div class="compare-card {role}">'
                        f'  <div class="compare-hdr">'
                        f'    <div class="sec-icon-wrap" style="background:{icon_bg};color:{title_color};">{icon_svg}</div>'
                        f'    <div class="compare-title" style="color:{title_color};">{hdr_txt_clean.upper()}</div>'
                        f'  </div>'
                        f'  <div class="sec-divider" style="background:{title_color}33;"></div>'
                        f'  <div class="sec-content">{conteudo}</div>'
                        f'</div>'
                    )

                partes = _r2.split(r'(<h[23][^>]*>.*?</h[23]>)', html_str, flags=_r2.DOTALL)
                output_parts = []
                buffer = []
                buffer_kind = None

                def flush_buffer():
                    nonlocal buffer, buffer_kind
                    if buffer:
                        if buffer_kind == 'compare':
                            output_parts.append('<div class="compare-grid">' + ''.join(buffer) + '</div>')
                        else:
                            output_parts.extend(buffer)
                    buffer = []
                    buffer_kind = None

                i2 = 0
                while i2 < len(partes):
                    parte = partes[i2]
                    m_hdr = _r2.match(r'<(h[23])[^>]*>(.*?)<\/h[23]>', parte, flags=_r2.DOTALL)
                    if m_hdr:
                        tag           = m_hdr.group(1)
                        hdr_txt       = m_hdr.group(2)
                        hdr_txt_clean = _limpar_titulo(hdr_txt)
                        conteudo      = partes[i2 + 1] if i2 + 1 < len(partes) else ""
                        i2 += 1

                        if tag == 'h2':
                            # Título de seção numerada (ex.: "1. Proposta de Valor")
                            # vira um banner leve.
                            flush_buffer()
                            output_parts.append(_make_banner(hdr_txt_clean))
                            # se vier texto/lista solta direto sob o h2 (ex.: Recomendações),
                            # agora também ganha um card em vez de ficar sem estilo.
                            if conteudo.strip():
                                output_parts.append(_make_plain_card(conteudo))
                        else:
                            lower_t       = hdr_txt_clean.lower()
                            is_numbered   = bool(_r2.match(r'^\d+[\.\)]\s', hdr_txt_clean))
                            is_own        = lower_t.startswith('minha empresa')
                            is_competitor = lower_t.startswith('concorrente')

                            if is_numbered:
                                # título de seção numerada (ex.: "1. Proposta de Valor")
                                # também vira banner leve, mesmo sendo h3 no markdown.
                                flush_buffer()
                                output_parts.append(_make_banner(hdr_txt_clean))
                                if conteudo.strip():
                                    output_parts.append(_make_plain_card(conteudo))
                            elif is_own or is_competitor:
                                # agrupa "Minha Empresa" + "Concorrente — X" lado a lado
                                if buffer_kind != 'compare':
                                    flush_buffer()
                                    buffer_kind = 'compare'
                                role = 'own' if is_own else 'competitor'
                                buffer.append(_make_compare_card(hdr_txt_clean, conteudo, role))
                            else:
                                flush_buffer()
                                output_parts.append(_make_card(hdr_txt_clean, conteudo))
                    else:
                        flush_buffer()
                        output_parts.append(parte)
                    i2 += 1

                flush_buffer()
                return ''.join(output_parts)

            import re as _re_promote
            html = _re_promote.sub(
                r'<p><strong>([^<]+?):?</strong></p>',
                r'<h3>\1</h3>',
                html
            )
            html = _wrap_section(html)
            return html

        relatorios_sites_html     = {str(i): _md_to_html_sites(a.get("relatorio","")) for i, a in enumerate(analises)}
        relatorios_sites_json     = _json_sites.dumps(relatorios_sites_html, ensure_ascii=False)
