                def _parse_ts(a):
                    raw = str(a.get("data_raw", "") or "").strip()
                    try:
                        ts = int(raw)
                        return ts if ts > 10**8 else 0
                    except Exception:
                        try:
                            return int(_dt.datetime.strptime(raw[:10], "%Y-%m-%d").timestamp())
                        except Exception:
                            return 0

